theorem eval_circleIntegral {F : ℂ → C(K, E)} {c : ℂ} {R : ℝ}
    (hF : CircleIntegrable F c R) (x : K) :
    (∮ z in C(c, R), F z) x = ∮ z in C(c, R), F z x

theorem hasDerivWithinAt_leftExtension_endpoint {a : ℝ} {L L' : V}
    {f f' : ℝ → V}
    (hderiv : ∀ x < a, HasDerivAt f (f' x) x)
    (hlim : Tendsto f (𝓝[<] a) (𝓝 L))
    (hlim' : Tendsto f' (𝓝[<] a) (𝓝 L')) :
    HasDerivWithinAt (leftExtension a L f) L' (Iic a) a

theorem directional_contDiffOn {s : Set (ℝ × X)} {f : (ℝ × X) → V}
    (hf : ContDiffOn ℝ ∞ f s) (hs : UniqueDiffOn ℝ s) (v : (ℝ × X)) :
    ContDiffOn ℝ ∞ (directional s f v) s

theorem normalIter_contDiffOn {s : Set (ℝ × X)} {f : (ℝ × X) → V}
    (hf : ContDiffOn ℝ ∞ f s) (hs : UniqueDiffOn ℝ s) (n : ℕ) :
    ContDiffOn ℝ ∞ (normalIter s f n) s

theorem glue_eqOn_future {W : Type*} {T : ℝ} {f g : (ℝ × X) → W}
    (hvalue : ∀ x : X, f (T, x) = g (T, x)) :
    EqOn (glue T f g) g (future T)
